"""Bangun dashboard HTML offline mandiri (gaya dashboard UTS) dari out/angka_dashboard.json.
Pakai: python scripts/buat_dashboard.py --nama "Helmi Riyadhoh" --nim 25110200005 --kelas Trad1
Semua angka berasal dari JSON hasil hitung_ulang; bagian Verifikasi menghitung ulang metrik forward dari log order mentah di browser."""
import json, argparse, re
ap = argparse.ArgumentParser()
ap.add_argument("--angka", default="out/angka_dashboard.json"); ap.add_argument("--keluar", default=None)
ap.add_argument("--nama", default="Helmi Riyadhoh"); ap.add_argument("--nim", default="25110200005"); ap.add_argument("--kelas", default="Trad1")
a = ap.parse_args()
D = json.load(open(a.angka)); D["identitas"] = {"nama": a.nama, "nim": a.nim, "kelas": a.kelas, "judul": "UAS Dashboard Algoritma Trading — Bot Dry Run Indodax"}
out = a.keluar or f"out/UAS_{a.nim}_{re.sub(r'[^A-Za-z]', '', a.nama)}.html"
T = r'''<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>UAS Dashboard Algoritma Trading</title><style>
:root{--bg:#fff6f9;--ink:#4a2338;--mut:#8a6478;--pk:#e6427f;--ln:#f3c9da;--up:#12915c;--dn:#d6284f}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,Segoe UI,Arial,sans-serif}
nav{position:sticky;top:0;background:#fff;border-bottom:1px solid var(--ln);padding:8px 16px;z-index:5;display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12.5px}
nav a{color:var(--pk);text-decoration:none}main{max-width:1180px;margin:auto;padding:18px}
section{background:#fff;border:1px solid var(--ln);border-radius:14px;padding:16px 18px;margin-bottom:16px}
h1{margin:0 0 4px;color:var(--pk)}h2{margin:0 0 10px;font-size:18px}h3{margin:16px 0 6px;font-size:14.5px}
.g{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}
.c{border:1px solid var(--ln);border-radius:10px;padding:10px 12px;background:#fffafc}.c small{display:block;color:var(--mut);font-size:11.5px}.c b{font-size:20px}.c i{display:block;font-style:normal;font-size:11.5px;color:var(--mut)}
table{border-collapse:collapse;width:100%;font-size:12.5px}th,td{border-bottom:1px solid #f7dde7;padding:5px 8px;text-align:right;white-space:nowrap}th{color:var(--mut);background:#fff3f8;position:sticky;top:0}
td:first-child,th:first-child{text-align:left}.w{overflow:auto;max-height:420px}.u{color:var(--up)}.d{color:var(--dn)}.m{color:var(--mut)}
.note{background:#fff3f8;border-left:4px solid var(--pk);padding:8px 12px;border-radius:6px;margin:8px 0;font-size:13px}.warn{border-color:#e08a00;background:#fff7e6}
svg{width:100%;height:auto}ul{margin:6px 0 6px 18px;padding:0}.ok{color:var(--up);font-weight:600}.bad{color:var(--dn);font-weight:600}
</style></head><body><nav id="nv"></nav><main id="m"></main>
<script id="d" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('d').textContent),I=D.identitas,P=D.parameter,B=D.backtest_3tahun,W=D.backtest_jendela_forward,F=D.forward,G=D.gap,S=D.kecocokan_sinyal,O=D.operasional,$=s=>document.querySelector(s);
const f=(v,n=2)=>v==null?'–':Number(v).toLocaleString('id-ID',{minimumFractionDigits:n,maximumFractionDigits:n});
const rp=v=>v==null?'–':(v<0?'-':'')+'Rp '+Math.abs(Math.round(v)).toLocaleString('id-ID');
const pc=(v,n=2)=>v==null?'–':f(v,n)+'%',cl=v=>v>0?'u':v<0?'d':'';
const tb=(h,r)=>'<div class="w"><table><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+r.map(x=>'<tr>'+x.map(y=>'<td>'+y+'</td>').join('')+'</tr>').join('')+'</table></div>';
const card=(a,b,c='')=>'<div class="c"><small>'+a+'</small><b>'+b+'</b><i>'+c+'</i></div>';
const sec=(id,t,h)=>'<section id="'+id+'"><h2>'+t+'</h2>'+h+'</section>';
const dt=ts=>new Date(ts*1000).toISOString().slice(0,10);
function line(S,o={}){const Wd=900,H=o.h||230,Pd=46,L=S.reduce((a,s)=>a.concat(s),[]);if(!L.length)return'<p class="m">Belum ada data.</p>';
 const x0=Math.min(...L.map(p=>p.x)),x1=Math.max(...L.map(p=>p.x)),y0=Math.min(...L.map(p=>p.y)),y1=Math.max(...L.map(p=>p.y)),X=x=>Pd+(x-x0)/((x1-x0)||1)*(Wd-Pd-8),Y=y=>H-18-(y-y0)/((y1-y0)||1)*(H-30),col=o.col||['#e6427f','#8a6478'];
 let s='<svg viewBox="0 0 '+Wd+' '+H+'">';for(let k=0;k<=3;k++){const v=y0+(y1-y0)*k/3,y=H-18-k/3*(H-30);s+='<line x1="'+Pd+'" x2="'+Wd+'" y1="'+y+'" y2="'+y+'" stroke="#f7dde7"/><text x="2" y="'+(y+4)+'" font-size="11" fill="#8a6478">'+f(v/1e6,1)+'jt</text>'}
 S.forEach((a,j)=>{const st=Math.max(1,Math.floor(a.length/700));s+='<polyline fill="none" stroke="'+col[j]+'" stroke-width="1.8" points="'+a.filter((_,i)=>i%st==0||i==a.length-1).map(p=>X(p.x).toFixed(1)+','+Y(p.y).toFixed(1)).join(' ')+'"/>'});
 return s+'<text x="'+Pd+'" y="'+(H-3)+'" font-size="11" fill="#8a6478">'+dt(x0)+'</text><text x="'+(Wd-70)+'" y="'+(H-3)+'" font-size="11" fill="#8a6478">'+dt(x1)+'</text></svg>'}
const kv=o=>Object.keys(o||{}).length?Object.entries(o).map(([k,v])=>k+': '+v).join(', '):'tidak ada';
function verif(){const ord=[...D.order_mentah].sort((a,b)=>a.ts-b.ts),op={},tr=[];
 ord.forEach(o=>{if(o.side=='BUY')op[o.pair]=o;else if(op[o.pair]){const b=op[o.pair];delete op[o.pair];tr.push(o.qty*o.avg_fill-o.fee-(b.qty*b.avg_fill+b.fee))}});
 const w=tr.filter(x=>x>0),l=tr.filter(x=>x<=0),sm=a=>a.reduce((x,y)=>x+y,0),eq=[100000000].concat(D.equity_forward.map(e=>e.equity));let pk=eq[0],md=0;eq.forEach(v=>{pk=Math.max(pk,v);md=Math.max(md,(pk-v)/pk*100)});
 const ret=(eq[eq.length-1]/eq[0]-1)*100,pf=l.length&&sm(l)?sm(w)/-sm(l):null,wr=tr.length?w.length/tr.length*100:null;
 const ck=(a,b,t)=>a==null&&b==null?true:(a!=null&&b!=null&&Math.abs(a-b)<t);
 const r=[['Jumlah trade tertutup',tr.length,F.n_trades,tr.length==F.n_trades],['Win rate (%)',f(wr),f(F.win_rate_pct),ck(wr,F.win_rate_pct,.01)],['Profit factor',f(pf,3),f(F.profit_factor,3),ck(pf,F.profit_factor,.001)],['Return total (%)',f(ret,3),f(F.return_total_pct,3),ck(ret,F.return_total_pct,.001)],['Max drawdown (%)',f(md,3),f(F.max_drawdown_pct,3),ck(md,F.max_drawdown_pct,.001)],['Avg untung (Rp)',w.length?rp(sm(w)/w.length):'–',rp(F.avg_win),ck(w.length?sm(w)/w.length:null,F.avg_win,1)],['Avg rugi (Rp)',l.length?rp(sm(l)/l.length):'–',rp(F.avg_loss),ck(l.length?sm(l)/l.length:null,F.avg_loss,1)]];
 return '<h3>Verifikasi: metrik forward dihitung ulang dari log order mentah (di browser ini)</h3>'+tb(['Metrik','Dari log order','Di kartu metrik','Cocok'],r.map(x=>[x[0],x[1],x[2],x[3]?'<span class="ok">✓</span>':'<span class="bad">✗</span>']))+'<p class="m"><b>Rumus:</b> trade = pasangan BUY→SELL per pair. Hasil (Rp) = qty jual × fill jual − fee jual − (qty beli × fill beli + fee beli). Return = equity panggilan terakhir ÷ Rp100.000.000 − 1. Drawdown dari equity tiap panggilan (equity = kas + posisi dinilai di best bid).</p>'}
let h='';
h+=sec('id','Identitas',`<h1>${I.judul}</h1><div class="g">${card('Nama',I.nama)}${card('NIM',I.nim)}${card('Kelas',I.kelas)}${card('Strategi',D.strategi)}${card('Universe',D.universe.join(', '))}${card('Fee taker dipakai',D.fee_taker_pct+'%','sumber & tanggal akses: lihat README')}${card('Forward test',f(D.jendela.durasi_hari,1)+' hari',D.jendela.panggilan_pertama+' s/d '+D.jendela.log_terakhir)}${card('Dihitung','UTC '+D.dibuat_utc,'dari log mentah oleh hitung_ulang.py')}</div>`+(D.jendela.durasi_hari<10?'<div class="note warn"><b>Catatan:</b> forward test berjalan '+f(D.jendela.durasi_hari,1)+' hari, lebih pendek dari 10 hari pada soal. Perbandingan memakai jendela yang sama persis. Jumlah trade sedikit sehingga return tidak signifikan secara statistik.</div>':''));
const par=Object.entries(P).map(([k,v])=>[k,Array.isArray(v)?v.join(', '):String(v)]);
h+=sec('aturan','Aturan strategi &amp; parameter (dibekukan)',`<p class="m">Timeframe 4 jam, long-only, tanpa short/margin/leverage. Sinyal dari bar tertutup; fill di ask (beli) dan bid (jual) order book live. Sinyal dipakai bersama oleh backtest dan bot (<code>core/strategy.py</code>).</p>`+tb(['Parameter','Nilai'],par));
const kartu=[['Return total',pc(F.return_total_pct),'forward · backtest jendela sama '+pc(W.return_total_pct)],['Max drawdown',pc(F.max_drawdown_pct),'forward · backtest jendela sama '+pc(W.max_drawdown_pct)],['Profit factor',f(F.profit_factor),F.n_trades+' trade tertutup'],['Win rate',pc(F.win_rate_pct),''],['Avg untung / trade',rp(F.avg_win),''],['Avg rugi / trade',rp(F.avg_loss),''],['Porsi biaya',pc(F.porsi_biaya_pct_dari_laba_kotor,1),'(fee+spread+slippage) ÷ laba kotor'],['Buy &amp; hold BTC/IDR',pc(F.buy_hold_btc_return_pct),'jendela forward, dari snapshot mentah']];
h+=sec('metrik','Metrik wajib — forward test',`<div class="g">${kartu.map(k=>card(...k)).join('')}</div><h3>Backtest vs forward</h3>`+tb(['Metrik','Backtest 3 tahun','Backtest, jendela forward','Forward test'],[['Return total',pc(B.return_total_pct),pc(W.return_total_pct),pc(F.return_total_pct)],['CAGR',pc(B.cagr_pct),'tidak bermakna','tidak ditampilkan'],['Max drawdown',pc(B.max_drawdown_pct),pc(W.max_drawdown_pct),pc(F.max_drawdown_pct)],['Profit factor',f(B.profit_factor),f(W.profit_factor),f(F.profit_factor)],['Win rate',pc(B.win_rate_pct),pc(W.win_rate_pct),pc(F.win_rate_pct)],['Avg untung (Rp)',rp(B.avg_win),rp(W.avg_win),rp(F.avg_win)],['Avg rugi (Rp)',rp(B.avg_loss),rp(W.avg_loss),rp(F.avg_loss)],['Jumlah trade',B.n_trades,W.n_trades,F.n_trades],['Porsi biaya',pc(B.porsi_biaya_pct_dari_laba_kotor,1),pc(W.porsi_biaya_pct_dari_laba_kotor,1),pc(F.porsi_biaya_pct_dari_laba_kotor,1)],['Buy &amp; hold BTC/IDR',pc(B.buy_hold_btc_return_pct),'–',pc(F.buy_hold_btc_return_pct)]])+verif());
h+=sec('gap','Gap backtest vs forward (jendela yang sama)',`<div class="g">${card('Return forward',pc(G.return_forward_pct))}${card('Return backtest, jendela sama',pc(G.return_backtest_jendela_pct))}${card('Gap',f(G.gap_pct_poin)+' poin %','forward − backtest')}${card('Selisih fill rata-rata',pc(G.selisih_fill_rata2_merugikan_pct,3),'positif = merugikan bot · '+G.order_dibandingkan+' order')}</div><div class="note">Biaya forward: fee ${rp(F.biaya_fee)} + spread ${rp(F.biaya_spread)} + slippage ${rp(F.biaya_slippage)}.</div>`);
h+=sec('ekuitas','Ekuitas',`<h3>Backtest 3 tahun (ekuitas harian, juta Rp)</h3>`+line([D.equity_backtest.map(e=>({x:e.ts,y:e.equity}))])+`<h3>Forward test (ekuitas tiap panggilan, juta Rp)</h3>`+line([D.equity_forward.map(e=>({x:e.ts,y:e.equity}))],{col:['#12915c']}));
h+=sec('sinyal','Kecocokan sinyal candle demi candle',`<div class="g">${card('Sinyal cocok',S.cocok+' / '+S.bar_dibandingkan,pc(S.cocok_pct)+' (target 100%)')}${card('ENTER/EXIT cocok',S.aksi_entry_exit_cocok+' / '+S.aksi_entry_exit)}${card('Bar tidak diproses bot',S.tidak_diproses_bot)}${card('Hanya ada di bot',S.hanya_di_bot)}</div>`+(S.selisih.length?tb(['Bar','Pair','Bot','Backtest'],S.selisih.map(r=>[r.bar,r.pair,r.bot,r.backtest])):'<div class="note">Tidak ada selisih sinyal.</div>'));
h+=sec('fill','Eksekusi: selisih harga fill per order',tb(['Waktu','Pair','Sisi','Fill bot','Fill backtest','Selisih merugikan','Telat (dtk)','Spread live','Komp. telat','Komp. spread','Komp. slip','Sisa'],D.fill.map(r=>[r.waktu,r.pair,r.sisi,f(r.fill_bot),f(r.fill_backtest),pc(r.selisih_merugikan_pct,3),f(r.terlambat_detik,0),pc(r.spread_live_pct,3),pc(r.komp_keterlambatan_pct,3),pc(r.komp_spread_pct,3),pc(r.komp_slippage_pct,3),pc(r.sisa_pct,4)]))+'<p class="m">Komponen menjelaskan selisih: keterlambatan jadwal (harga pasar saat bot jalan vs open bar berikutnya di backtest), spread live vs asumsi, slippage vs asumsi. Sisa = belum terjelaskan.</p>');
h+=sec('spread','Spread &amp; slippage: dipakai backtest vs seluruh snapshot',tb(['Pair','Spread dipakai','Spread semua snapshot','Slippage dipakai','Slippage semua snapshot','Jumlah snapshot'],D.spread_vs_snapshot.map(r=>[r.pair,pc(r.spread_dipakai_backtest_pct,3),pc(r.spread_semua_snapshot_pct,3),f(r.slippage_dipakai_pct,4)+'%',f(r.slippage_semua_snapshot_pct,4)+'%',r.n_snapshot])));
h+=sec('ops','Panel operasional',`<div class="g">${card('Panggilan terlaksana',O.panggilan_terlaksana+' / '+O.panggilan_terjadwal_seharusnya,'dilewati lock: '+O.panggilan_dilewati_lock)}${card('Uptime',pc(O.uptime_pct,1),O.candle_pair_tepat_waktu+'/'+O.candle_pair_total+' candle-pair tepat waktu')}${card('Error API',O.error_total,kv(O.error_per_tahap))}${card('Kill switch dipakai',O.kill_switch_event)}${card('Daily loss limit terpicu',O.daily_loss_limit_event)}${card('Keterlambatan median',f(O.keterlambatan_median_detik,0)+' dtk','maks '+f(O.keterlambatan_maks_detik,0)+' dtk')}${card('Idempotency menolak',O.idempotent_skip,'panggilan ganda')}</div><div class="note">Definisi uptime: ${O.definisi_uptime}.<br>Entry diblokir: ${kv(O.entry_diblokir)}. Data tidak valid: ${kv(O.invalid_data)}.</div>`);
h+=sec('harian','Ekuitas harian (panggilan pertama setelah 00.00 WIB)',tb(['Waktu','Ekuitas (Rp)'],D.equity_harian.map(r=>[r.waktu,rp(r.equity)])));
$('#m').innerHTML=h;$('#nv').innerHTML=[['id','Identitas'],['aturan','Aturan'],['metrik','Metrik'],['gap','Gap'],['ekuitas','Ekuitas'],['sinyal','Sinyal'],['fill','Fill'],['spread','Spread'],['ops','Operasional'],['harian','Harian']].map(x=>'<a href="#'+x[0]+'">'+x[1]+'</a>').join('');
</script></body></html>'''
open(out, "w", encoding="utf-8").write(T.replace("__DATA__", json.dumps(D, default=float).replace("</", "<\\/")))
print("OK ->", out)
